// Parse Claude output
let parsed;
try {
  const raw = $('Claude: Extract UT Fields').first().json.text || $('Claude: Extract UT Fields').first().json.output || '';
  parsed = JSON.parse(raw);
} catch (e) {
  return [{ json: { valid: false, missing: ['Could not parse Claude output: ' + e.message], extracted: null } }];
}

const { customerName, items } = parsed;
const missing = [];

if (!customerName) missing.push('customerName (company/customer name)');
if (!items || items.length === 0) missing.push('at least one part/line item with geometry details');

const GEOMETRY_REQUIREMENTS = {
  FLAT_BAR:    ['thickness', 'width', 'length'],
  CSCAN_FLAT:  ['thickness', 'width', 'length'],
  THIN_SHEET:  ['thickness', 'width', 'length'],
  ROUND_BAR:   ['diameter', 'length'],
  CSCAN_ROUND: ['diameter', 'length'],
  RING:        ['outerDiameter', 'innerDiameter', 'length'],
  TUBING:      ['diameter', 'length'],
};

if (items) {
  items.forEach((item, i) => {
    const prefix = items.length > 1 ? `Item ${i+1}: ` : '';
    if (!item.geometryType) {
      missing.push(`${prefix}geometryType (one of: FLAT_BAR, ROUND_BAR, RING, TUBING, CSCAN_FLAT, CSCAN_ROUND, THIN_SHEET)`);
    } else {
      const required = GEOMETRY_REQUIREMENTS[item.geometryType] || [];
      for (const field of required) {
        if (!item[field] || item[field] <= 0) {
          missing.push(`${prefix}${field} (required for ${item.geometryType})`);
        }
      }
    }
    if (!item.quantity || item.quantity < 1) {
      missing.push(`${prefix}quantity`);
    }
  });
}

return [{ json: {
  valid: missing.length === 0,
  missing,
  extracted: parsed,
  emailFrom: $('IMAP Email Trigger').first().json.from.text,
  emailMessageId: $('IMAP Email Trigger').first().json.messageId,
  emailSubject: $('IMAP Email Trigger').first().json.subject,
} }];

const quote = $('POST /api/ut/quote').first().json;
const items = quote.items || [];

const rowsHtml = items.map(item => {
  const dims = item.dimensions || {};
  const dimStr = Object.entries(dims)
    .filter(([, v]) => v !== undefined && v !== null)
    .map(([k, v]) => `${k}: ${v}"`)
    .join(', ');
  return `
    <tr>
      <td>${item.geometryType}</td>
      <td>${dimStr}</td>
      <td>${item.pricing.quantity}</td>
      <td>$${item.pricing.grandTotal.toFixed(2)}</td>
    </tr>`;
}).join('');

const html = `<!DOCTYPE html>
<html>
<head>
<meta charset="utf-8">
<style>
  body { font-family: Arial, sans-serif; padding: 40px; color: #222; }
  h1 { color: #1a56db; }
  table { width: 100%; border-collapse: collapse; margin-top: 20px; }
  th { background: #1a56db; color: white; padding: 10px; text-align: left; }
  td { padding: 10px; border-bottom: 1px solid #ddd; }
  .summary { margin-top: 20px; text-align: right; font-size: 1.1em; }
  .total { font-weight: bold; font-size: 1.3em; color: #1a56db; }
  .footer { margin-top: 40px; font-size: 0.85em; color: #888; }
</style>
</head>
<body>
<h1>NDT Ultrasonic Testing Quote</h1>
<p><strong>Quote #:</strong> ${quote.quoteNumber}<br>
<strong>Customer:</strong> ${quote.customer.name}<br>
<strong>Date:</strong> ${new Date(quote.generatedAt).toLocaleDateString()}<br>
<strong>Lead Time:</strong> ${quote.customer.leadTime || 'Standard'}</p>

<table>
  <thead><tr><th>Geometry</th><th>Dimensions</th><th>Qty</th><th>Total</th></tr></thead>
  <tbody>${rowsHtml}</tbody>
</table>

<div class="summary">
  <p>Subtotal: $${(quote.summary.totalGrand - quote.summary.totalEnvFees - quote.summary.totalTechFees).toFixed(2)}</p>
  <p>Tech Fees: $${quote.summary.totalTechFees.toFixed(2)}</p>
  <p>Env Fees: $${quote.summary.totalEnvFees.toFixed(2)}</p>
  <p class="total">Grand Total: $${quote.summary.totalGrand.toFixed(2)}</p>
</div>

<div class="footer">
  <p>This quote is valid for 30 days. Contact us to confirm delivery and scheduling.</p>
</div>
</body></html>`;

return [{ json: { html, quoteNumber: quote.quoteNumber, quoteId: quote.quoteId, grandTotal: quote.summary.totalGrand } }];

